export default function prepare({ text }) {
  if (typeof text !== "string" || !text.trim()) throw Error("Enter a keyword request");
  return {
    input: [
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text:
              "Extract exactly one SEO keyword from the message. Correct spelling only, do not rephrase. Return only the keyword. Message: " +
              text,
          },
        ],
      },
    ],
  };
}

