export default function query({ response }) {
  if (response?.status !== "completed" || !Array.isArray(response.output))
    throw Error("Keyword extraction failed");
  const keyword = response.output
    .flatMap((x) => x.content || [])
    .filter((x) => x.type === "output_text")
    .map((x) => x.text)
    .join("")
    .trim();
  if (!keyword || keyword.length > 80 || keyword.includes("\n"))
    throw Error("Expected one keyword up to 80 characters");
  return { keyword, body: [{ keywords: [keyword] }] };
}

