export default function result({ keyword, volume, ideas, volumeStatus, ideasStatus }) {
  function task(body, status) {
    if (
      status < 200 ||
      status >= 300 ||
      !body ||
      body.status_code !== 20000 ||
      !Array.isArray(body.tasks) ||
      body.tasks[0]?.status_code !== 20000 ||
      !Array.isArray(body.tasks[0].result)
    )
      throw Error("Keyword API failed");
    return body.tasks[0].result;
  }
  const main = task(volume, volumeStatus).find(
      (x) => String(x.keyword).toLowerCase() === keyword.toLowerCase(),
    ),
    related = task(ideas, ideasStatus)
      .filter((x) => String(x.keyword).toLowerCase() !== keyword.toLowerCase())
      .slice(0, 10);
  function fields(x) {
    if (!x) return null;
    return {
      keyword: x.keyword,
      avg_monthly_searches: x.search_volume ?? null,
      competition_index: x.competition_index ?? null,
      competition_value: x.competition ?? null,
      high_cpc: x.high_top_of_page_bid ?? null,
      low_cpc: x.low_top_of_page_bid ?? null,
    };
  }
  if (!main) throw Error("No metrics for requested keyword");
  return { data: [fields(main), ...related.map(fields)] };
}

