export default function format({ data }) {
  return {
    input: [
      {
        role: "user",
        content: [
          {
            type: "input_text",
            text:
              "Format these keyword metrics clearly. Preserve values and label missing data; do not invent metrics: " +
              JSON.stringify(data),
          },
        ],
      },
    ],
  };
}

